			// first subquest: its Cooking xp counts towards the others' Cooking levels
			q(RECIPE_FOR_DISASTER__PIRATE_PETE, 1).after(RECIPE_FOR_DISASTER__ANOTHER_COOKS_QUEST).skill(COOKING, 31),
