			f(THE_LOST_TRIBE, 1).after(GOBLIN_DIPLOMACY, RUNE_MYSTERIES).skill(AGILITY, 13).skill(THIEVING, 13).skill(MINING, 17),
			f(ELEMENTAL_WORKSHOP_I, 1).skill(MINING, 20).skill(SMITHING, 20).skill(CRAFTING, 20),
