			f(DEATH_ON_THE_ISLE, 2).after(CHILDREN_OF_THE_SUN).skill(THIEVING, 34).skill(AGILITY, 32),
			f(THE_GIANT_DWARF, 2).skill(CRAFTING, 12).skill(FIREMAKING, 16).skill(MAGIC, 33).skill(THIEVING, 14),
			f(SPIRITS_OF_THE_ELID, 2).skill(MAGIC, 33).skill(RANGED, 37).skill(MINING, 37).skill(THIEVING, 37),
			q(ALFRED_GRIMHANDS_BARCRAWL, 0),
			q(HORROR_FROM_THE_DEEP, 2).after(ALFRED_GRIMHANDS_BARCRAWL).skill(AGILITY, 35),
			q(RECIPE_FOR_DISASTER__LUMBRIDGE_GUIDE, 1)
				.after(RECIPE_FOR_DISASTER__ANOTHER_COOKS_QUEST, BIG_CHOMPY_BIRD_HUNTING, BIOHAZARD, DEMON_SLAYER, MURDER_MYSTERY, NATURE_SPIRIT, WITCHS_HOUSE)
				.skill(COOKING, 40),
			q(RECIPE_FOR_DISASTER__SKRACH_UGLOGWEE, 1).after(RECIPE_FOR_DISASTER__ANOTHER_COOKS_QUEST, BIG_CHOMPY_BIRD_HUNTING).skill(COOKING, 41).skill(FIREMAKING, 20),
			f(WATCHTOWER, 4).after(DRUIDIC_RITUAL).skill(MAGIC, 15).skill(THIEVING, 15).skill(AGILITY, 25).skill(HERBLORE, 14).skill(MINING, 40)),

			stage("High-level requirements",
			q(TEMPLE_OF_IKOV, 1).skill(THIEVING, 42).skill(RANGED, 40),
			// before Family Crest: its 20,000 Magic xp counts towards Family Crest's Magic 59
			q(DESERT_TREASURE_I, 3)
				.after(THE_DIG_SITE, TEMPLE_OF_IKOV, THE_TOURIST_TRAP, TROLL_STRONGHOLD, PRIEST_IN_PERIL, WATERFALL_QUEST)
				.skill(THIEVING, 53).skill(MAGIC, 50).skill(FIREMAKING, 50).skill(SLAYER, 10),
			q(FAMILY_CREST, 1).skill(MINING, 40).skill(SMITHING, 40).skill(MAGIC, 59).skill(CRAFTING, 40).note("lvl 170 demon, safespottable"),
			q(HEROES_QUEST, 1).after(SHIELD_OF_ARRAV, LOST_CITY, MERLINS_CRYSTAL, DRAGON_SLAYER_I, DRUIDIC_RITUAL).qpReq(55)
				.skill(COOKING, 53).skill(FISHING, 53).skill(HERBLORE, 25).skill(MINING, 50).note("needs a partner"),
			q(LEGENDS_QUEST, 0).startOnly().after(FAMILY_CREST, HEROES_QUEST, SHILO_VILLAGE, UNDERGROUND_PASS, WATERFALL_QUEST).qpReq(107)
				.note("only until you can enter Kharazi Jungle"),
			q(RECIPE_FOR_DISASTER__SIR_AMIK_VARZE, 1)
				.after(RECIPE_FOR_DISASTER__ANOTHER_COOKS_QUEST, FAMILY_CREST, HEROES_QUEST, SHILO_VILLAGE, UNDERGROUND_PASS, WATERFALL_QUEST)
				.qpReq(107).note("needs Kharazi Jungle access, lvl 227 black dragon"),
			q(RECIPE_FOR_DISASTER__KING_AWOWOGEI, 1).after(RECIPE_FOR_DISASTER__ANOTHER_COOKS_QUEST, MONKEY_MADNESS_I)
				.skill(COOKING, 70).skill(AGILITY, 48),
			q(RECIPE_FOR_DISASTER__CULINAROMANCER, 1)
				.after(RECIPE_FOR_DISASTER__WARTFACE__BENTNOZE, RECIPE_FOR_DISASTER__MOUNTAIN_DWARF, RECIPE_FOR_DISASTER__PIRATE_PETE,
					RECIPE_FOR_DISASTER__LUMBRIDGE_GUIDE, RECIPE_FOR_DISASTER__EVIL_DAVE, RECIPE_FOR_DISASTER__SKRACH_UGLOGWEE,
					RECIPE_FOR_DISASTER__SIR_AMIK_VARZE, RECIPE_FOR_DISASTER__KING_AWOWOGEI, DESERT_TREASURE_I, HORROR_FROM_THE_DEEP)
				.qpReq(175).note("no Prayer allowed in the fights"))
		).flatMap(List::stream).collect(Collectors.toList());
	}

	/** The steps of {@code route} that {@code targets} need, themselves or as prerequisites, in route order. */
	private static List<Step> needed(List<Step> route, Quest... targets)
	{
		Map<Quest, Step> byQuest = route.stream().collect(Collectors.toMap(s -> s.quest, s -> s));
		Set<Quest> need = EnumSet.noneOf(Quest.class);
		Deque<Quest> open = new ArrayDeque<>(Arrays.asList(targets));
		while (!open.isEmpty())
		{
			Quest q = open.pop();
			if (need.add(q))
			{
				open.addAll(byQuest.get(q).after);
			}
		}
		return route.stream().filter(s -> need.contains(s.quest)).collect(Collectors.toList());
	}

	/** Stage a long generated route by the quest points you'll have when you reach each step: "0-50 QP", "50-100 QP", ... */
	private static List<Step> byQp(List<Step> route)
	{
		int qp = 0;
		for (Step s : route)
		{
			int band = qp / 50 * 50;
			s.stage = band + "-" + (band + 50) + " QP";
			qp += s.qp;
		}
		return route;
	}

	/** Tag steps with the route section the panel groups them under. */
	private static List<Step> stage(String name, Step... steps)
	{
		for (Step s : steps)
		{
			s.stage = name;
		}
		return List.of(steps);
	}
}

package com.accountbuildplanner;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.DefaultListCellRenderer;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.PluginErrorPanel;
import net.runelite.client.ui.components.ThinProgressBar;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;
import net.runelite.client.util.AsyncBufferedImage;

/** Sidebar shell: build picker + Start, progress summary, and the Next / Route / Skills tabs. */
class BuildPlannerPanel extends PluginPanel
{
	private final JComboBox<Build> builds = new JComboBox<>(Build.values());
	private final JButton start = new JButton("Start");
	private final JPanel body = new JPanel(new BorderLayout()); // holds either the message or the plan
	private final PluginErrorPanel message = new PluginErrorPanel();
	private final JPanel planBox = new JPanel(new BorderLayout(0, 6));
	private final JLabel summary = small();
	private final JLabel percent = small();
	private final ThinProgressBar progress = Ui.bar(0, 1, ColorScheme.BRAND_ORANGE);
	private final JPanel display = new JPanel();
	private final MaterialTabGroup tabs = new MaterialTabGroup(display);
	private final NextView next;
	private final RouteView route;
	private final SkillsView skills;
	private final MaterialTab nextTab;
	private boolean planned;

	BuildPlannerPanel(SkillIconManager skillIcons, ItemManager items, Consumer<Build> onStart)
	{
		Map<Build, ImageIcon> icons = new EnumMap<>(Build.class);
		for (Build b : Build.values())
		{
			AsyncBufferedImage img = items.getImage(b.icon);
			icons.put(b, new ImageIcon(img));
			img.onLoaded(builds::repaint);
		}
		builds.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected, boolean focus)
			{
				super.getListCellRendererComponent(list, value, index, selected, focus);
				setIcon(icons.get((Build) value));
				return this;
			}
		});

		start.setToolTipText("Read your quests and levels and plan the next steps");
		start.setFocusPainted(false);
		start.addActionListener(e ->
		{
			start.setText("Refresh");
			onStart.accept((Build) builds.getSelectedItem());
		});

		JPanel picker = new JPanel(new BorderLayout(6, 0));
		picker.setOpaque(false);
		picker.add(builds, BorderLayout.CENTER);
		picker.add(start, BorderLayout.EAST);

		JPanel summaryRow = new JPanel(new BorderLayout());
		summaryRow.setOpaque(false);
		summaryRow.add(summary, BorderLayout.WEST);
		summaryRow.add(percent, BorderLayout.EAST);
		progress.setPreferredSize(new Dimension(0, 6));

		JPanel status = new JPanel(new BorderLayout(0, 4));
		status.setOpaque(false);
		status.add(summaryRow, BorderLayout.NORTH);
		status.add(progress, BorderLayout.SOUTH);

		route = new RouteView(skillIcons);
		MaterialTab routeTab = new MaterialTab("Route", tabs, route);
		next = new NextView(skillIcons, () -> tabs.select(routeTab));
		nextTab = new MaterialTab("Next", tabs, next);
		skills = new SkillsView(skillIcons);
		tabs.addTab(nextTab);
		tabs.addTab(routeTab);
		tabs.addTab(new MaterialTab("Skills", tabs, skills));
		tabs.setBorder(new EmptyBorder(4, 0, 2, 0));

		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(status, BorderLayout.NORTH);
		top.add(tabs, BorderLayout.SOUTH);

		display.setOpaque(false);
		planBox.setOpaque(false);
		planBox.add(top, BorderLayout.NORTH);
		planBox.add(display, BorderLayout.CENTER);
		body.setOpaque(false);

		add(picker);
		add(body);
		showMessage("Pick a build and press Start.");
	}

	void showMessage(String text)
	{
		message.setContent("Account Build Planner", text);
		swap(message);
	}

	void showPlan(Planner.Plan p)
	{
		int total = p.done + p.todo.size();
		summary.setText(p.done + " of " + total + " quests" + (p.qpTarget > 0 ? ", " + p.qp + "/" + p.qpTarget + " QP" : ""));
		percent.setText((total == 0 ? 100 : p.done * 100 / total) + "%");
		progress.setMaximumValue(Math.max(1, total));
		progress.setValue(p.done);

		next.show(p);
		route.show(p);
		skills.show(p);
		if (!planned)
		{
			planned = true;
			tabs.select(nextTab); // only the first time, so refreshes keep whatever tab you're on
		}
		swap(planBox);
	}

	private void swap(JComponent c)
	{
		body.removeAll();
		body.add(c, BorderLayout.CENTER);
		body.revalidate();
		body.repaint();
	}

	private static JLabel small()
	{
		JLabel l = new JLabel();
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(Ui.MUTED);
		return l;
	}
}

package com.accountbuildplanner;

import java.awt.BorderLayout;
import java.awt.Color;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/** Next tab: the job to do now, what it needs, and the few steps after it. */
class NextView extends JPanel
{
	private final SkillIconManager skillIcons;
	private final Runnable showRoute;

	NextView(SkillIconManager skillIcons, Runnable showRoute)
	{
		super(new DynamicGridLayout(0, 1, 0, 4));
		this.skillIcons = skillIcons;
		this.showRoute = showRoute;
		setOpaque(false);
	}

	void show(Planner.Plan p)
	{
		removeAll();
		if (p.nextStep == null)
		{
			add(unlocked(p.next));
		}
		else
		{
			add(Ui.header("Next job"));
			add(card(p));
			if (p.alt != null)
			{
				add(Ui.header("Can do now instead"));
				add(Ui.questRow(p.alt, "", false));
			}
			List<Planner.Item> then = p.route.stream()
				.dropWhile(i -> i.status != Planner.Status.NEXT)
				.skip(1)
				.limit(3)
				.collect(Collectors.toList());
			if (!then.isEmpty())
			{
				add(Ui.header("Then"));
				for (int i = 0; i < then.size(); i++)
				{
					add(Ui.itemRow(then.get(i), skillIcons, "<font color='#7f7f7f'>" + (i + 2) + "</font>&nbsp;&nbsp;"));
				}
				JLabel more = Ui.link("See full route", showRoute);
				more.setBorder(new EmptyBorder(2, 0, 0, 0));
				add(more);
			}
		}
		revalidate();
		repaint();
	}

	private JPanel card(Planner.Plan p)
	{
		Step s = p.nextStep;
		JPanel body = new JPanel(new DynamicGridLayout(0, 1, 0, 3));
		body.setOpaque(false);

		JLabel title = new JLabel(Ui.html(Ui.esc((s.startOnly ? "Start " : "") + s.quest.getName()), Ui.CARD));
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		body.add(title);
		body.add(Ui.muted((s.qp > 0 ? "+" + s.qp + " QP" : "No quest points") + (s.filler ? ", filler quest" : ""), Ui.CARD));
		if (s.note != null)
		{
			body.add(Ui.muted(s.note, Ui.CARD));
		}

		if (!p.checklist.isEmpty())
		{
			JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
			list.setOpaque(false);
			list.setBorder(new EmptyBorder(6, 0, 4, 0));
			p.checklist.forEach(r -> list.add(requirement(r)));
			body.add(list);
		}

		JButton guide = new JButton("Quest guide");
		guide.setFocusPainted(false);
		guide.addActionListener(e -> Ui.wiki(s.quest.getName()));
		body.add(guide);

		JLabel icon = new JLabel(new ImageIcon(Ui.QUEST_ICON));
		icon.setVerticalAlignment(SwingConstants.TOP);

		JPanel card = new JPanel(new BorderLayout(8, 0));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(8, 8, 8, 8));
		card.add(icon, BorderLayout.WEST);
		card.add(body, BorderLayout.CENTER);
		return Ui.accent(card, ColorScheme.BRAND_ORANGE);
	}

	private static JPanel requirement(Planner.Req r)
	{
		JLabel mark = new JLabel(new ImageIcon(r.met ? Ui.TICK : Ui.CROSS));
		mark.setVerticalAlignment(SwingConstants.TOP);
		JLabel text = new JLabel(Ui.html(Ui.esc(r.text), Ui.CARD - 22));
		text.setFont(FontManager.getRunescapeSmallFont());
		text.setForeground(r.met ? Ui.MUTED : Color.WHITE);

		JPanel line = new JPanel(new BorderLayout(4, 0));
		line.setOpaque(false);
		line.add(mark, BorderLayout.WEST);
		line.add(text, BorderLayout.CENTER);
		if (!r.met && r.skill != null)
		{
			line.setToolTipText("Click for the wiki training guide");
			Ui.onClick(line, () -> Ui.wiki(r.skill.getName() + " training"));
		}
		return line;
	}

	private static JPanel unlocked(String text)
	{
		JLabel title = new JLabel(Ui.html(Ui.esc(text), Ui.CARD));
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);

		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(12, 10, 12, 10));
		card.add(title, BorderLayout.CENTER);
		return Ui.accent(card, ColorScheme.PROGRESS_COMPLETE_COLOR);
	}
}

package com.accountbuildplanner;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/** Pure logic: account snapshot + build route -> what to do next. No client access, so it's unit-testable. */
final class Planner
{
	/** Snapshot of the account, read on the client thread. */
	static final class Account
	{
		final Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		int qp;

		boolean finished(Quest q)
		{
			return quests.getOrDefault(q, QuestState.NOT_STARTED) == QuestState.FINISHED;
		}

		boolean done(Step s)
		{
			return s.startOnly
				? quests.getOrDefault(s.quest, QuestState.NOT_STARTED) != QuestState.NOT_STARTED
				: finished(s.quest);
		}

		int level(Skill s)
		{
			return levels.getOrDefault(s, 1);
		}
	}

	enum Status
	{
		DONE, NEXT, TODO, TRAIN
	}

	/** A route row: a quest, or training placed right before the first quest that needs it. */
	static final class Item
	{
		final Step step;
		final Skill skill;
		final int level;
		final Status status;
		final String stage; // training rows take the stage of the quest they're for

		Item(Step step, Skill skill, int level, Status status, String stage)
		{
			this.step = step;
			this.skill = skill;
			this.level = level;
			this.status = status;
			this.stage = stage;
		}

		String text()
		{
			return step != null ? step.label() : "Train " + skill.getName() + " to " + level;
		}
	}

	static final class SkillGoal
	{
		final Skill skill;
		final int level;
		final int target;
		final int xp;
		final int targetXp;

		SkillGoal(Skill skill, int level, int target, int xp)
		{
			this.skill = skill;
			this.level = level;
			this.target = target;
			this.xp = xp;
			this.targetXp = Experience.getXpForLevel(target);
		}

		boolean met()
		{
			return level >= target;
		}
	}

	/** One requirement of a step, worded for a checklist. */
	static final class Req
	{
		final String text;
		final boolean met;
		final Skill skill; // null unless it's a level requirement

		Req(String text, boolean met, Skill skill)
		{
			this.text = text;
			this.met = met;
			this.skill = skill;
		}
	}

	static final class Plan
	{
		String next;
		Step nextStep;   // null once the build is done
		Step alt;        // something doable now when nextStep is blocked
		int done;
		int qp;
		int qpTarget;
		int skipped;     // filler quests not needed for the QP target
		final List<Step> todo = new ArrayList<>();
		final List<Item> route = new ArrayList<>(); // every planned row, done ones too, in route order
		final List<SkillGoal> skills = new ArrayList<>();
		List<Req> checklist = List.of(); // nextStep's requirements
	}

	static Plan plan(Build build, Account acc)
	{
		Plan p = new Plan();
		List<Step> route = build.route;
		p.qp = acc.qp;
		// Only builds that use filler quests aim for a QP total. For the rest QP is a side effect, and showing
		// "150/20 QP" to someone with QP from other quests would be noise.
		p.qpTarget = route.stream().anyMatch(s -> s.filler) ? route.stream().mapToInt(s -> s.qpReq).max().orElse(0) : 0;

		// QP the fillers must cover = target - what you have - what the remaining required quests give.
		// Steps that themselves need the target (the final boss) don't count, you need the QP before them.
		int fillerQp = p.qpTarget - acc.qp - route.stream()
			.filter(s -> !s.filler && s.qpReq < p.qpTarget && !acc.done(s))
			.mapToInt(s -> s.qp)
			.sum();

		// Highest level each done or planned step asks for (skipped filler doesn't count)
		Map<Skill, Integer> reqs = new EnumMap<>(Skill.class);
		// Levels the plan has already asked you to train to, so "Train X to N" sits before the first quest needing it
		Map<Skill, Integer> goal = new EnumMap<>(acc.levels);
		for (Step s : route)
		{
			if (acc.done(s))
			{
				p.done++;
				p.route.add(new Item(s, null, 0, Status.DONE, s.stage));
				s.skills.forEach((k, v) -> reqs.merge(k, v, Math::max));
				continue;
			}
			if (s.filler)
			{
				if (fillerQp <= 0)
				{
					p.skipped++;
					continue;
				}
				fillerQp -= s.qp;
			}
			s.skills.forEach((k, v) ->
			{
				reqs.merge(k, v, Math::max);
				if (v > goal.getOrDefault(k, acc.level(k)))
				{
					goal.put(k, v);
					p.route.add(new Item(null, k, v, Status.TRAIN, s.stage));
				}
			});
			p.route.add(new Item(s, null, 0, p.todo.isEmpty() ? Status.NEXT : Status.TODO, s.stage));
			p.todo.add(s);
		}

		goal.forEach((skill, lvl) ->
		{
			if (lvl > acc.level(skill))
			{
				p.skills.add(new SkillGoal(skill, acc.level(skill), lvl, acc.xp.getOrDefault(skill, 0)));
			}
		});
		// Then skills already at the build's highest requirement
		reqs.forEach((skill, lvl) ->
		{
			if (acc.level(skill) >= lvl)
			{
				p.skills.add(new SkillGoal(skill, acc.level(skill), lvl, acc.xp.getOrDefault(skill, 0)));
			}
		});

		if (p.todo.isEmpty())
		{
			p.next = build.displayName + " unlocked!";
			return p;
		}

		Step first = p.todo.get(0);
		p.nextStep = first;
		p.checklist = checklist(first, acc);
		String block = blocker(first, acc);
		if (block == null)
		{
			p.next = first.label();
			return p;
		}

		p.next = block + "\nfor " + first.label();
		// Planned steps first, then any skipped filler.
		p.alt = Stream.concat(p.todo.stream(), route.stream())
			.filter(s -> s != first && !acc.done(s) && blocker(s, acc) == null)
			.findFirst()
			.orElse(null);
		return p;
	}

	/** Every requirement of a step: quests first, then levels, then quest points. Unmet ones say what to do. */
	static List<Req> checklist(Step s, Account acc)
	{
		List<Req> list = new ArrayList<>();
		for (Quest q : s.after)
		{
			boolean met = acc.finished(q);
			list.add(new Req((met ? "Finished " : "Finish ") + q.getName(), met, null));
		}
		s.skills.forEach((skill, req) ->
		{
			int lvl = acc.level(skill);
			boolean met = lvl >= req;
			list.add(new Req(met ? skill.getName() + " " + req
				: "Train " + skill.getName() + " to " + req + " (now " + lvl + ")", met, skill));
		});
		if (s.qpReq > 0)
		{
			boolean met = acc.qp >= s.qpReq;
			list.add(new Req(met ? s.qpReq + " quest points"
				: "Get " + s.qpReq + " quest points (now " + acc.qp + ")", met, null));
		}
		return list;
	}

	/** What stops you doing this step right now, or null if you can do it. */
	static String blocker(Step s, Account acc)
	{
		String need = checklist(s, acc).stream().filter(r -> !r.met).map(r -> r.text).collect(Collectors.joining("\n"));
		return need.isEmpty() ? null : need;
	}
}

package com.accountbuildplanner;

import java.awt.BorderLayout;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/** Route tab: the whole route by stage, done quests ticked, finished stages folded. */
class RouteView extends JPanel
{
	private final SkillIconManager skillIcons;
	private final Map<String, Boolean> open = new HashMap<>(); // stages the user folded or unfolded
	private Planner.Plan shown;

	RouteView(SkillIconManager skillIcons)
	{
		super(new DynamicGridLayout(0, 1, 0, 4));
		this.skillIcons = skillIcons;
		setOpaque(false);
	}

	void show(Planner.Plan p)
	{
		shown = p;
		removeAll();
		Map<String, List<Planner.Item>> stages = p.route.stream()
			.collect(Collectors.groupingBy(i -> i.stage, LinkedHashMap::new, Collectors.toList()));
		stages.forEach((stage, rows) ->
		{
			long quests = rows.stream().filter(i -> i.step != null).count();
			long done = rows.stream().filter(i -> i.status == Planner.Status.DONE).count();
			boolean isOpen = open.getOrDefault(stage, done < quests);
			add(stageHeader(stage, done, quests, isOpen));
			if (isOpen)
			{
				for (Planner.Item i : rows)
				{
					JPanel row = Ui.itemRow(i, skillIcons, "");
					add(i.status == Planner.Status.NEXT ? Ui.accent(row, ColorScheme.BRAND_ORANGE) : row);
				}
			}
		});
		if (p.skipped > 0)
		{
			JLabel skipped = Ui.muted(p.skipped + " filler quests not needed, you'll have the QP", Ui.FULL);
			skipped.setBorder(new EmptyBorder(6, 0, 0, 0));
			add(skipped);
		}
		revalidate();
		repaint();
	}

	private JPanel stageHeader(String stage, long done, long quests, boolean isOpen)
	{
		JLabel name = Ui.header(stage);
		name.setIcon(new ImageIcon(isOpen ? Ui.OPEN : Ui.SHUT));
		name.setIconTextGap(4);

		JLabel count = new JLabel(done + "/" + quests);
		count.setFont(FontManager.getRunescapeSmallFont());
		count.setForeground(done == quests ? ColorScheme.PROGRESS_COMPLETE_COLOR : Ui.MUTED);
		count.setBorder(new EmptyBorder(8, 0, 0, 0));

		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		header.add(name, BorderLayout.CENTER);
		header.add(count, BorderLayout.EAST);
		header.setToolTipText(isOpen ? "Click to fold this stage" : "Click to show this stage");
		Ui.onClick(header, () ->
		{
			open.put(stage, !isOpen);
			show(shown);
		});
		return header;
	}
}

package com.accountbuildplanner;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/** Skills tab: every skill the build needs, like the in-game skills tab. Orange = to train, green = met. */
class SkillsView extends JPanel
{
	private final SkillIconManager skillIcons;

	SkillsView(SkillIconManager skillIcons)
	{
		super(new DynamicGridLayout(0, 1, 0, 6));
		this.skillIcons = skillIcons;
		setOpaque(false);
	}

	void show(Planner.Plan p)
	{
		removeAll();
		long met = p.skills.stream().filter(Planner.SkillGoal::met).count();
		JLabel summary = Ui.muted(p.skills.isEmpty() ? "No skill requirements" : met + " of " + p.skills.size() + " met", Ui.FULL);
		summary.setBorder(new EmptyBorder(8, 0, 0, 0));
		add(summary);

		if (!p.skills.isEmpty())
		{
			JPanel grid = new JPanel(new GridLayout(0, 2, 4, 4));
			grid.setOpaque(false);
			p.skills.forEach(g -> grid.add(cell(g)));
			add(grid);
		}
		revalidate();
		repaint();
	}

	private JPanel cell(Planner.SkillGoal g)
	{
		JLabel levels = new JLabel(g.level + "/" + g.target);
		levels.setFont(FontManager.getRunescapeSmallFont());
		levels.setForeground(g.met() ? ColorScheme.PROGRESS_COMPLETE_COLOR : Color.WHITE);

		JPanel body = new JPanel(new BorderLayout(0, 4));
		body.add(levels, BorderLayout.NORTH);
		body.add(Ui.bar(g.xp, g.targetXp, g.met() ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BRAND_ORANGE), BorderLayout.SOUTH);

		String name = g.skill.getName();
		String tip = g.met()
			? String.format("%s: done, the build needs level %d. Click for the wiki training guide.", name, g.target)
			: String.format("%s: %,d xp to level %d. Click for the wiki training guide.", name, Math.max(0, g.targetXp - g.xp), g.target);
		return Ui.row(skillIcons.getSkillImage(g.skill, true), body, name + " training", tip);
	}
}

package com.accountbuildplanner;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * One quest in a build route, plus what it needs before you can do it.
 * Filler steps exist only to reach the build's quest point target and are skipped once it's covered.
 */
final class Step
{
	final Quest quest;
	final int qp;
	final boolean filler;
	final Map<Skill, Integer> skills = new EnumMap<>(Skill.class);
	final List<Quest> after = new ArrayList<>();
	int qpReq;
	boolean startOnly;
	String note;
	String stage; // route section, set by Build

	private Step(Quest quest, int qp, boolean filler)
	{
		this.quest = quest;
		this.qp = qp;
		this.filler = filler;
	}

	static Step q(Quest quest, int qp)
	{
		return new Step(quest, qp, false);
	}

	static Step f(Quest quest, int qp)
	{
		return new Step(quest, qp, true);
	}

	Step skill(Skill skill, int level)
	{
		skills.put(skill, level);
		return this;
	}

	Step after(Quest... quests)
	{
		after.addAll(Arrays.asList(quests));
		return this;
	}

	Step qpReq(int qp)
	{
		qpReq = qp;
		return this;
	}

	/** Done as soon as the quest is started (e.g. Legends' Quest for Recipe for Disaster). */
	Step startOnly()
	{
		startOnly = true;
		return this;
	}

	Step note(String note)
	{
		this.note = note;
		return this;
	}

	String label()
	{
		return (startOnly ? "Start " : "") + quest.getName() + (note == null ? "" : " (" + note + ")");
	}
}

